"use client"

import * as React from "react"
import { accentChain } from "glimm"
import { GlimmScope, type GlimmScopeHandle } from "glimm/react"

const palette = accentChain(["#30D158", "#3CD3FE", "#6B5DFF"])
const page = "#1c1c1f"
const panel = "#26262a"
const line = "rgba(255,255,255,.08)"
const skeleton = "rgba(255,255,255,.085)"
const skeletonHi = "rgba(255,255,255,.15)"
const muted = "rgba(255,255,255,.30)"
const green = "#30D158"
const widths = [182,150,212,168,132]

function SidebarRow({ width, active, badge }: { width:number; active?:boolean; badge?:boolean }) {
  return <div style={{ alignItems:"center", background:active?"rgba(255,255,255,.06)":"transparent", borderRadius:6, display:"flex", gap:9, margin:"0 -8px", padding:"6px 8px" }}><span style={{ background:skeleton, borderRadius:4, height:15, width:15 }} /><span style={{ background:skeleton, borderRadius:3, height:8, width }} />{badge && <span style={{ background:skeleton, borderRadius:999, height:14, marginLeft:"auto", width:14 }} />}</div>
}

function Check({ checked }: { checked:boolean }) {
  return <span aria-hidden="true" style={{ alignItems:"center", background:checked?green:"transparent", borderRadius:6, boxShadow:checked?"none":`inset 0 0 0 1.6px ${muted}`, color:"#fff", display:"flex", flexShrink:0, fontSize:14, height:19, justifyContent:"center", transition:"background-color 140ms ease", width:19 }}>{checked && "✓"}</span>
}

function TasksScene() {
  const scope = React.useRef<GlimmScopeHandle>(null)
  const [checked, setChecked] = React.useState([true,true,false,false,false])
  const [started, setStarted] = React.useState(false)
  const [busy, setBusy] = React.useState(false)
  const [done, setDone] = React.useState(false)

  React.useEffect(() => { if (!done) return; const id = window.setTimeout(()=>setDone(false),3200); return()=>window.clearTimeout(id) }, [done])
  const toggle = (index:number, element:HTMLButtonElement) => {
    if (busy) return
    setStarted(true)
    const next = checked.slice(); next[index] = !next[index]; setChecked(next)
    if (next.every(Boolean)) {
      setBusy(true)
      const rect = element.getBoundingClientRect()
      scope.current?.play({ at:[rect.left+rect.width/2,rect.top+rect.height/2], anticipate:true, change:()=>setDone(true), onBurst:()=>setBusy(false) })
    } else setDone(false)
  }

  return <GlimmScope ref={scope} palette={palette} sweepMs={2700} style={{ inset:0, position:"absolute" }}><main style={{ background:page, color:"#ECECEE", display:"flex", flexDirection:"column", fontFamily:"Inter,ui-sans-serif,system-ui,sans-serif", height:"100%", minHeight:560, overflow:"hidden", position:"relative" }}>
    <header style={{ alignItems:"center", borderBottom:`1px solid ${line}`, display:"flex", height:40, justifyContent:"space-between", padding:"0 14px", position:"relative" }}><div style={{ display:"flex", gap:7 }}>{["#FF5F57","#FEBC2E","#28C840"].map(c=><span key={c} style={{ background:c, borderRadius:999, height:11, width:11 }} />)}</div><span style={{ background:skeletonHi, borderRadius:3, height:14, left:"50%", position:"absolute", top:"50%", transform:"translate(-50%,-50%)", width:52 }} /><span style={{ background:skeleton, borderRadius:4, height:16, width:16 }} /></header>
    <div style={{ display:"flex", flex:1, minHeight:0 }}><aside style={{ background:page, borderRight:`1px solid ${line}`, flexShrink:0, overflow:"hidden", padding:"14px 10px", width:210 }}>{[150,96,124,110,88].map((w,i)=><SidebarRow badge={i===1} key={w} width={w} />)}<div style={{ height:18 }} />{[104,84].map(w=><SidebarRow key={w} width={w} />)}<div style={{ height:18 }} /><SidebarRow active width={118} /></aside>
      <section style={{ background:panel, flex:1, minWidth:0, overflow:"auto", padding:"34px 38px 44px" }}><div style={{ maxWidth:520 }}><div style={{ alignItems:"center", display:"flex", gap:11 }}><span style={{ borderRadius:999, boxShadow:`inset 0 0 0 1.7px ${muted}`, height:19, width:19 }} /><span style={{ background:skeletonHi, borderRadius:3, height:14, width:132 }} /></div><span style={{ background:skeleton, borderRadius:3, display:"block", height:8, marginLeft:30, marginTop:15, width:60 }} /><div style={{ display:"grid", gap:2, marginTop:30 }}>{widths.map((width,index)=><button aria-checked={checked[index]} aria-label={`Task ${index+1}`} key={index} onClick={(event)=>toggle(index,event.currentTarget)} role="checkbox" style={{ alignItems:"center", background:"transparent", border:0, borderRadius:8, color:"inherit", cursor:"pointer", display:"flex", gap:13, padding:"10px", position:"relative", width:"100%" }}><Check checked={checked[index]} /><span style={{ background:skeletonHi, borderRadius:3, height:9, opacity:checked[index]?.36:1, transition:"opacity 160ms ease", width }} />{index===4 && !started && <span aria-hidden="true" style={{ fontFamily:"cursive", fontSize:17, left:width+54, position:"absolute", top:10, transform:"rotate(-2deg)", whiteSpace:"nowrap" }}>← Check these off</span>}</button>)}</div></div></section>
    </div>
    <div role="status" style={{ alignItems:"center", background:"#37373C", borderRadius:999, boxShadow:`inset 0 0 0 1px ${line},0 4px 14px rgba(0,0,0,.24)`, display:"flex", fontSize:13, gap:8, left:"50%", opacity:done?1:0, padding:"6px 12px 6px 8px", pointerEvents:"none", position:"absolute", top:52, transform:`translate(-50%,${done?0:-4}px)`, transition:"opacity 200ms ease-out,transform 200ms ease-out" }}><span style={{ color:green }}>✓</span><span>All tasks done</span></div>
  </main></GlimmScope>
}

export default function GlimmToDos() { return <TasksScene /> }
export { GlimmToDos }
